{
  "title": "Facebook Public Profiles Scraper Input",
  "description": "Extract publicly visible identity, bio, work, education, location, follower signals, and links from Facebook profile URLs. No Facebook login is required.",
  "type": "object",
  "schemaVersion": 1,
  "required": [
    "startUrls"
  ],
  "properties": {
    "startUrls": {
      "sectionCaption": "Profile extraction",
      "sectionDescription": "Add a JSON array of public Facebook profile URLs and choose the maximum number of useful records to save.",
      "title": "Facebook profile URLs",
      "description": "Public facebook.com profile URLs supplied as strings or {\"url\": \"...\"} objects. Username URLs, profile.php URLs with a numeric id, and /people/<name>/<numeric-id> permalinks are supported. Page sections, posts, groups, search URLs, blank entries, and entries without a usable URL are reported as uncharged per-input diagnostics without stopping valid profiles in the same batch.",
      "type": "array",
      "editor": "json",
      "minItems": 1,
      "maxItems": 1000,
      "prefill": [
        {
          "url": "https://www.facebook.com/profile.php?id=4"
        }
      ]
    },
    "maxItems": {
      "title": "Maximum profiles",
      "description": "Stop after this many useful profile records. Duplicate input URLs are processed once.",
      "type": "integer",
      "default": 100,
      "prefill": 1,
      "minimum": 1,
      "maximum": 1000
    }
  }
}
